 const r=createControlledRenderer(()=>createElement(LearningDraftProvider,{cache:f.cache,children:createElement(LearningDraftScope,{owner:f.owner,children:createElement(PickingHelperStudio,{data:f.module.data as never,state,onAction:action=>{actions.push(action);return Promise.resolve(true);}})})}));r.render();
