test('actual non-consuming apply registers the quit barrier and preserves a newer run-note generation durably',async()=>{
 const f=await fixture(true);let state=await f.read(),release!:()=>void,entered!:()=>void;const held=new Promise<void>(r=>{release=r;}),arrived=new Promise<void>(r=>{entered=r;});let operation:Promise<boolean>|undefined;
 const r=createControlledRenderer(()=>createElement(LearningDraftProvider,{cache:f.cache,children:createElement(LearningDraftScope,{owner:f.owner,children:createElement(PickingHelperStudio,{data:f.module.data as never,state,onAction:(action:PickingAction)=>{operation=(async()=>{const next=await f.act(action as never);if(action.kind==='picking-apply'){entered();await held;}state=next;r.render();return true;})();return operation;}})})}));r.render();
 // Select the real prepared run through its public typed control.
 await f.cache.flush();button(r,'Apply this local manifest').props.onClick();await arrived;
 try{input(r,r.nodes().some(n=>n.type==='label'&&text(n)==='Run note')?'Run note':'Version note').props.onChange({target:{value:'Newer mirror note after local commit'}});r.render();await f.cache.flush();const slot='helper:table:run',raw=(await records(f.store)).find(record=>record.slot===slot)!;expect(JSON.parse(raw.value!.value).note).toBe('Newer mirror note after local commit');
  f.cache.setFrozen(true);let finished=false;const quitting=f.cache.flushForQuit().then(()=>{finished=true;});await tick();expect.soft(finished).toBe(false);release();await operation;await quitting;expect(finished).toBe(true);expect((await f.read()).attempts[0].status).toBe('completed');expect((await f.read()).contexts.at(-1)!.target.revision).toBe(1);const saved=(await records(f.store)).find(record=>record.slot===slot)!;expect(saved.value).toEqual(raw.value);expect(f.cache.getSnapshot().entries[learningDraftKey(f.owner,slot)].local).toEqual(raw.value);
  await f.core.close();const reopened=await createCompanion({dataDir:f.directory});try{const next=new LearningDraftStore({directory:f.directory,lookupTask:async id=>(await reopened.listTasks()).find(t=>t.id===id)}),savedRecords=await records(next);expect(savedRecords.find(record=>record.slot===slot)!.value).toEqual(raw.value);const recovery=createLearningDrafts({read:()=>next.read(),save:(...args)=>next.save(...args)});await recovery.load();const task=await reopened.getTask(f.target.taskId),review=createControlledRenderer(()=>createElement(LearningDraftReview,{task,cache:recovery}));review.render();expect(review.nodes().map(text).join(' ')).toContain('Newer mirror note after local commit');}finally{await reopened.close();}
 }finally{release();await operation;f.cache.setFrozen(false);}
});

