function controlledPicking(f:Awaited<ReturnType<typeof fixture>>,core:Awaited<ReturnType<typeof createCompanion>>,cache:ReturnType<typeof createLearningDrafts>,initial:PickingState){
 let state=initial,last:Promise<boolean>|undefined;const submissions:Promise<void>[]=[],original=cache.runSubmission,spy=vi.spyOn(cache,'runSubmission').mockImplementation(work=>{const result=original(work);submissions.push(result);return result;});
 const r=createControlledRenderer(()=>createElement(LearningDraftProvider,{cache,children:createElement(LearningDraftScope,{owner:f.owner,children:createElement(PickingHelperStudio,{data:f.module.data as never,state,onAction:action=>{last=(async()=>{await editModule(core,{...f.target,action});const task=await core.getTask(f.target.taskId);state=pickingHelper.parseState(f.module.data.kind==='helper-studio'?f.module.data.id:'',task.session!.moduleStates[0].state);r.render();return true;})();return last;}})})}));r.render();
 return {r,cache,get state(){return state;},restore:()=>spy.mockRestore(),change(label:string,value:string){input(r,label).props.onChange({target:{value}});r.render();},async click(label:string){const count=submissions.length;button(r,label).props.onClick();await vi.waitFor(()=>expect(submissions.length).toBeGreaterThan(count));await submissions[count];await last;await cache.flush();r.render();},async newId(){button(r,'Choose a new run identifier').props.onClick();r.render();await cache.flush();return input(r,'Run identifier').props.value as string;}};
}

