  const defaultId=input(view.r,'Run identifier').props.value as string,selected=mode==='typed'?`custom-${settle}`:await view.newId();if(mode==='typed')view.change('Run identifier',selected);expect(selected).not.toBe(defaultId);view.change('Run note',`Exact ${mode} ${settle} preview`);await view.click('Preview local manifest');expect(input(view.r,'Run identifier').props.value).toBe(selected);expect(view.state.attempts.find(a=>a.id===selected)!.status).toBe('prepared');expect(button(view.r,'Apply this local manifest').props.disabled).toBe(false);expect(button(view.r,'Cancel this run')).toBeDefined();const retained=(await records(f.store)).find(record=>record.slot==='helper:table:run')!.value;expect(retained).not.toBeNull();
