test('failed case-draft write preserves prior durable bytes and the new reviewed input until explicit storage retry',async()=>{
 const f=await fixture(true,false),state=await completedFeedback(f),r=createControlledRenderer(()=>createElement(LearningDraftProvider,{cache:f.cache,children:createElement(LearningDraftScope,{owner:f.owner,children:createElement(PickingHelperStudio,{data:f.module.data as never,state,onAction:()=>Promise.resolve(true)})})}));r.render();input(r,'Case 1 expected handling').props.onChange({target:{value:'Prior durable unrelated input'}});r.render();await f.cache.flush();const path=join(f.directory,'learning-drafts.json'),bytes=await readFile(path),task=await f.core.getTask(f.target.taskId),choice=reviewSavedRun(r,'feedbackReady'),save=vi.spyOn(f.store,'save').mockRejectedValueOnce(Error('Owned storage write failure'));
 try{
  choice.props.onChange({target:{value:'stop:stockStop'}});r.render();await expect(f.cache.flush()).rejects.toThrow(/Owned storage write failure/);r.render();expect(await readFile(path)).toEqual(bytes);const entry=f.cache.getSnapshot().entries[learningDraftKey(f.owner,'helper:table:cases')],raw=JSON.parse(entry.local!.value);expect(raw.cases).toHaveLength(8);expect(raw.cases[0].expected.output.handling).toBe('Prior durable unrelated input');expect(raw.cases.at(-1).expected).toEqual({status:'abstained',code:'explicit-stop',haltedStepId:'stockStop'});expect(r.nodes().some(node=>node.props.role==='alert'&&text(node).includes('Unfinished practice could not be saved'))).toBe(true);save.mockRestore();button(r,'Retry saving practice drafts').props.onClick();await vi.waitFor(()=>expect(f.cache.getSnapshot().entries[learningDraftKey(f.owner,'helper:table:cases')].error).toBeUndefined());await f.cache.flush();expect(JSON.parse((await records(f.store)).find(record=>record.slot==='helper:table:cases')!.value!.value)).toEqual(raw);expect(await f.core.getTask(f.target.taskId)).toEqual(task);
 }finally{save.mockRestore();}
});
